cat >> /workspace/submission/engine.hpp << 'EOF'

// ------------------------------------------------------------- planner -----
// Exact joint optimization of tree shape, node encoding and residency over
// all versions of one case under the shared resident-page budget.
//
// Work of a node covering runs [i,j) of version v:
//   P*(hit|miss)*T + (ceil(K/lanes[mode])+decode[mode])*Q
// where P = allocated/64, K = key count, T = repeat-weighted touched bursts
// and Q = repeat-weighted address visits inside [i,j).  image_pages adds
// P for every node plus the fixed header and padded hop array.  The search
// minimizes work first, then image_pages, using the additive key
// work*SCALE + pages with SCALE above any reachable page total.
typedef __int128 Cst;
static const Cst CST_INF = (Cst)1 << 124;
static const Cst CST_SCALE = (Cst)1 << 20;
static const int MAXB = 9;
static const int MAXP = 12;

struct VersionInput {
    int R;
    std::vector<Key> starts;
    std::vector<int> hops;
    std::vector<std::pair<long long, std::vector<int> > > bursts;
};

struct VersionPlan {
    std::vector<Cst> cost;                     // exact resident page count
    std::vector<std::vector<Layout> > layouts;
};

inline VersionPlan plan_version(const VersionInput& v, int C, int hit, int miss,
                                const int* dec) {
    const int R = v.R;
    const int P1 = C + 1;
    const size_t SZ = (size_t)(R + 1) * (R + 1);
    const size_t GZ = SZ * (MAXB + 1);

    std::vector<long long> wsum(R + 1, 0);
    {
        std::vector<long long> w(R, 0);
        for (size_t t = 0; t < v.bursts.size(); ++t) {
            const std::vector<int>& rs = v.bursts[t].second;
            const long long rep = v.bursts[t].first;
            for (size_t k = 0; k < rs.size(); ++k) w[rs[k]] += rep;
        }
        for (int k = 0; k < R; ++k) wsum[k + 1] = wsum[k] + w[k];
    }
    std::vector<long long> T(SZ, 0);
    for (size_t t = 0; t < v.bursts.size(); ++t) {
        const std::vector<int>& rs = v.bursts[t].second;
        if (rs.empty()) continue;
        const long long rep = v.bursts[t].first;
        std::vector<int> pc(R + 1, 0);
        {
            std::vector<char> mark(R, 0);
            for (size_t k = 0; k < rs.size(); ++k) mark[rs[k]] = 1;
            int c = 0;
            for (int k = 0; k < R; ++k) { pc[k] = c; c += mark[k]; }
            pc[R] = c;
        }
        for (int i = 0; i < R; ++i)
            for (int j = i + 1; j <= R; ++j)
                if (pc[j] > pc[i]) T[(size_t)i * (R + 1) + j] += rep;
    }

    std::vector<Cst> Fe(SZ * P1, CST_INF);
    std::vector<Cst> Ge(GZ * P1, CST_INF);
    std::vector<int> Fc(SZ * P1, -1);
    std::vector<int> Gc(GZ * P1, -1);

#define FEID(i, s) (((size_t)(i) * (R + 1) + (s)) * P1)
#define GEID(i, s, b) ((((size_t)(i) * (R + 1) + (s)) * (MAXB + 1) + (b)) * P1)

    std::vector<char> ok0(SZ, 1), ok1(SZ, 0), ok2(SZ, 0);
    for (int i = 0; i < R; ++i)
        for (int s = 1; i + s <= R; ++s) {
            const Key spread = v.starts[i + s - 1] - v.starts[i];
            const size_t id = (size_t)i * (R + 1) + s;
            if (spread < ((Key)1 << 64)) ok1[id] = 1;
            if (spread < ((Key)1 << 32)) ok2[id] = 1;
        }

    // Costs are leaf/internal node contributions plus the node's own pages.
    long long* Tp = T.data();
    auto leaf_cost = [&](int i, int s, int m, int cached) -> Cst {
        const int P = (32 + s * KW[m] + 63) / 64;
        const long long q = wsum[i + s] - wsum[i];
        const long long t = Tp[(size_t)i * (R + 1) + i + s];
        const long long coeff = (s + LN[m] - 1) / LN[m] + dec[m];
        const Cst work = (Cst)P * (cached ? hit : miss) * t + (Cst)coeff * q;
        return work * CST_SCALE + (Cst)P;
    };
    auto int_cost = [&](int i, int s, int b, int m, int cached) -> Cst {
        const int P = (32 + 4 * b + (b - 1) * KW[m] + 63) / 64;
        const long long q = wsum[i + s] - wsum[i];
        const long long t = Tp[(size_t)i * (R + 1) + i + s];
        const long long coeff = ((b - 1) + LN[m] - 1) / LN[m] + dec[m];
        const Cst work = (Cst)P * (cached ? hit : miss) * t + (Cst)coeff * q;
        return work * CST_SCALE + (Cst)P;
    };

    for (int s = 1; s <= R; ++s) {
        const int bmax = std::min(MAXB, s);
        for (int b = 2; b <= bmax; ++b) {
            for (int i = 0; i + s <= R; ++i) {
                Cst* dst = &Ge[GEID(i, s, b)];
                int* dc = &Gc[GEID(i, s, b)];
                for (int r = 0; r <= C; ++r) { dst[r] = CST_INF; dc[r] = -1; }
                for (int d = b - 1; d <= s - 1; ++d) {
                    const Cst* g = &Ge[GEID(i, d, b - 1)];
                    const int* gc = &Gc[GEID(i, d, b - 1)];
                    for (int r1 = 0; r1 <= C; ++r1) {
                        const Cst gv = g[r1];
                        if (gv >= CST_INF) continue;
                        const Cst* f = &Fe[FEID(i + d, s - d)];
                        for (int r2 = 0; r1 + r2 <= C; ++r2) {
                            const Cst fv = f[r2];
                            if (fv >= CST_INF) continue;
                            const int r = r1 + r2;
                            const Cst c = gv + fv;
                            if (c < dst[r]) { dst[r] = c; dc[r] = (d << 4) | r1; }
                        }
                    }
                }
            }
        }
        for (int i = 0; i + s <= R; ++i) {
            Cst* best = &Fe[FEID(i, s)];
            int* ch = &Fc[FEID(i, s)];
            const long long q = wsum[i + s] - wsum[i];
            const long long t = Tp[(size_t)i * (R + 1) + i + s];
            (void)q; (void)t;
            const size_t id = (size_t)i * (R + 1) + s;
            for (int r = 0; r <= C; ++r) { best[r] = CST_INF; ch[r] = -1; }
            if (s <= 8) {
                for (int m = 0; m < 3; ++m) {
                    if (m == 1 && !ok1[id]) continue;
                    if (m == 2 && !ok2[id]) continue;
                    const int P = (32 + s * KW[m] + 63) / 64;
                    const long long coeff = (s + LN[m] - 1) / LN[m] + dec[m];
                    const Cst body = (Cst)coeff * q;
                    const Cst c0 = (body + (Cst)P * miss * t) * CST_SCALE + (Cst)P;
                    if (c0 < best[0]) { best[0] = c0; ch[0] = (cached_flag(0) << 2) | m; }
                    if (P <= C) {
                        const Cst c1 = (body + (Cst)P * hit * t) * CST_SCALE + (Cst)P;
                        if (c1 < best[P]) { best[P] = c1; ch[P] = (1 << 2) | m; }
                    }
                }
            }
            for (int b = 2; b <= bmax; ++b) {
                const Cst* g = &Ge[GEID(i, s, b)];
                for (int m = 0; m < 3; ++m) {
                    if (m == 1 && !ok1[id]) continue;
                    if (m == 2 && !ok2[id]) continue;
                    const int P = (32 + 4 * b + (b - 1) * KW[m] + 63) / 64;
                    const long long coeff = ((b - 1) + LN[m] - 1) / LN[m] + dec[m];
                    const Cst body = (Cst)coeff * q;
                    const Cst c0 = (body + (Cst)P * miss * t) * CST_SCALE + (Cst)P;
                    for (int r = 0; r <= C; ++r) {
                        if (g[r] >= CST_INF) continue;
                        const Cst c = c0 + g[r];
                        if (c < best[r]) { best[r] = c; ch[r] = (1 << 7) | (b << 3) | m; }
                    }
                    if (P <= C) {
                        const Cst c1 = (body + (Cst)P * hit * t) * CST_SCALE + (Cst)P;
                        for (int r = P; r <= C; ++r) {
                            if (g[r - P] >= CST_INF) continue;
                            const Cst c = c1 + g[r - P];
                            if (c < best[r]) { best[r] = c; ch[r] = (1 << 7) | (b << 3) | (1 << 2) | m; }
                        }
                    }
                }
            }
        }
        for (int i = 0; i + s <= R; ++i) {
            const Cst* f = &Fe[FEID(i, s)];
            Cst* g = &Ge[GEID(i, s, 1)];
            for (int r = 0; r <= C; ++r) g[r] = f[r];
        }
    }
#undef GEID
#undef FEID

    VersionPlan vp;
    vp.cost.assign(P1, CST_INF);
    vp.layouts.assign(P1, std::vector<Layout>());
    struct TN { int lo, span, mode, cached, id; std::vector<TN*> ch; };
    std::vector<TN*> pool;
    for (int r = 0; r <= C; ++r) {
        if (Fe[FEID(0, R) + r] >= CST_INF) continue;
        vp.cost[r] = Fe[FEID(0, R) + r];
        std::function<TN*(int, int, int)> build_fe;
        std::function<void(int, int, int, int, std::vector<TN*>&)> build_parts;
        build_fe = [&](int i, int s, int rr) -> TN* {
            const int c = Fc[FEID(i, s) + rr];
            const int mode = c & 3;
            const int cached = (c >> 2) & 1;
            TN* n = new TN();
            n->lo = i; n->span = s; n->mode = mode; n->cached = cached;
            n->id = (int)pool.size();
            pool.push_back(n);
            if (!((c >> 7) & 1)) return n;
            const int b = (c >> 3) & 15;
            const int pages = (32 + 4 * b + (b - 1) * KW[mode] + 63) / 64;
            build_parts(i, s, b, rr - (cached ? pages : 0), n->ch);
            return n;
        };
        build_parts = [&](int i, int s, int b, int rr, std::vector<TN*>& out) {
            if (b == 1) { out.push_back(build_fe(i, s, rr)); return; }
            const int g = Gc[GEID(i, s, b) + rr];
            const int d = g >> 4;
            const int r1 = g & 15;
            build_parts(i, d, b - 1, r1, out);
            out.push_back(build_fe(i + d, s - d, rr - r1));
        };
        TN* root = build_fe(0, R, r);
        std::vector<TN*> order;
        order.push_back(root);
        for (size_t k = 0; k < order.size(); ++k)
            for (size_t x = 0; x < order[k]->ch.size(); ++x)
                order.push_back(order[k]->ch[x]);
        std::vector<int> index(pool.size(), -1);
        std::vector<Layout> nodes;
        for (size_t k = 0; k < order.size(); ++k) {
            index[order[k]->id] = (int)k;
            Layout L;
            L.lo = order[k]->lo;
            L.span = order[k]->span;
            L.mode = order[k]->mode;
            L.cached = order[k]->cached;
            nodes.push_back(L);
        }
        for (size_t k = 0; k < order.size(); ++k)
            for (size_t x = 0; x < order[k]->ch.size(); ++x)
                nodes[k].children.push_back(index[order[k]->ch[x]->id]);
        vp.layouts[r] = nodes;
        for (size_t k = 0; k < pool.size(); ++k) delete pool[k];
        pool.clear();
    }
    return vp;
}
